"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[46807],{3331:(e,a,o)=>{o.d(a,{R:()=>n,x:()=>l});var i=o(36672);const s={},r=i.createContext(s);function n(e){const a=i.useContext(r);return i.useMemo((function(){return"function"==typeof e?e(a):{...a,...e}}),[a,e])}function l(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:n(e.components),i.createElement(r.Provider,{value:a},e.children)}},51394:(e,a,o)=>{o.r(a),o.d(a,{assets:()=>d,contentTitle:()=>l,default:()=>u,frontMatter:()=>n,metadata:()=>i,toc:()=>c});const i=JSON.parse('{"id":"2023/04/14","title":"2023-04-14","description":"Arrest made in SF killing of Bob Lee - alleged killer also worked in tech","source":"@site/i18n/es/docusaurus-plugin-content-docs/current/2023/04/14.md","sourceDirName":"2023/04","slug":"/2023/04/14","permalink":"/es/2023/04/14","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/es/docusaurus-plugin-content-docs//current/2023/04/14.md","tags":[],"version":"current","frontMatter":{"localized_date":"14 de abril de 2023","top_news":"Arrest made in SF killing of Bob Lee - alleged killer also worked in tech"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-15","permalink":"/es/2023/04/15"},"next":{"title":"2023-04-13","permalink":"/es/2023/04/13"}}');var s=o(23420),r=o(3331);const n={localized_date:"14 de abril de 2023",top_news:"Arrest made in SF killing of Bob Lee - alleged killer also worked in tech"},l="2023-04-14",d={},c=[{value:"Arrest made in SF killing of Bob Lee - alleged killer also worked in tech",id:"arrest-made-in-sf-killing-of-bob-lee---alleged-killer-also-worked-in-tech",level:2},{value:"La prohibici\xf3n del alojamiento en YouTube-DL allana el camino a la censura privatizada",id:"la-prohibici\xf3n-del-alojamiento-en-youtube-dl-allana-el-camino-a-la-censura-privatizada",level:2},{value:"El arte de la autoingenier\xeda",id:"el-arte-de-la-autoingenier\xeda",level:2},{value:"Apple utilizar\xe1 cobalto 100% reciclado en sus bater\xedas para 2025",id:"apple-utilizar\xe1-cobalto-100-reciclado-en-sus-bater\xedas-para-2025",level:2},{value:"Logramos multiplicar por 6 la velocidad de arranque de Podman",id:"logramos-multiplicar-por-6-la-velocidad-de-arranque-de-podman",level:2},{value:"Mejora de Tailscale a trav\xe9s del c\xf3digo abierto de Apple",id:"mejora-de-tailscale-a-trav\xe9s-del-c\xf3digo-abierto-de-apple",level:2},{value:"Dibujos animados",id:"dibujos-animados",level:2},{value:"Amazon CodeWhisperer, gratuito para uso individual, ya est\xe1 disponible de forma generalizada",id:"amazon-codewhisperer-gratuito-para-uso-individual-ya-est\xe1-disponible-de-forma-generalizada",level:2},{value:"Google ya ha retirado seis productos en 2023",id:"google-ya-ha-retirado-seis-productos-en-2023",level:2},{value:"Ya est\xe1 disponible el c\xf3digo abierto de Nvidia RTX Remix Runtime",id:"ya-est\xe1-disponible-el-c\xf3digo-abierto-de-nvidia-rtx-remix-runtime",level:2}];function t(e){const a={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.header,{children:(0,s.jsx)(a.h1,{id:"2023-04-14",children:"2023-04-14"})}),"\n",(0,s.jsx)(a.h2,{id:"arrest-made-in-sf-killing-of-bob-lee---alleged-killer-also-worked-in-tech",children:"Arrest made in SF killing of Bob Lee - alleged killer also worked in tech"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://missionlocal.org/2023/04/bob-lee-killing-arrest-made-san-francisco/",children:"Original"}),".\nSe ha producido una detenci\xf3n en el asesinato del ejecutivo tecnol\xf3gico Bob Lee, y el presunto asesino tambi\xe9n trabajaba en tecnolog\xeda y era conocido de Lee. Al parecer, la polic\xeda encontr\xf3 a Lee y al sospechoso conduciendo juntos en un coche registrado a nombre del sospechoso, y alega que se produjo alg\xfan tipo de enfrentamiento mientras estaban en el veh\xedculo y que posiblemente continu\xf3 despu\xe9s de que Lee se marchara. La cobertura de la muerte de Lee se ha empaquetado con otras desgracias y cr\xedmenes recientes de San Francisco, aunque esto no representa con exactitud la experiencia real vivida por la mayor\xeda de los sanfranciscanos."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35555525",children:"Discussion Service"}),".\nEl asesinato de un ejecutivo tecnol\xf3gico en San Francisco ha suscitado debates sobre factores como la falta de vivienda, la salud mental, la drogadicci\xf3n y la pobreza que pueden haber conducido al crimen, pero los comentaristas advierten que no se deben hacer generalizaciones. Tambi\xe9n se debate sobre el uso de estad\xedsticas frente a las an\xe9cdotas personales a la hora de evaluar los \xedndices de delincuencia, y sobre la necesidad de un enfoque que implique a la comunidad para abordar los complejos problemas de las personas sin hogar, la adicci\xf3n y la delincuencia. Los usuarios destacan la importancia de evaluar los niveles de delincuencia en relaci\xf3n con la pobreza, en lugar de comparar culturas diferentes, y de no sacar conclusiones precipitadas bas\xe1ndose en un solo caso."]}),"\n",(0,s.jsx)(a.h2,{id:"la-prohibici\xf3n-del-alojamiento-en-youtube-dl-allana-el-camino-a-la-censura-privatizada",children:"La prohibici\xf3n del alojamiento en YouTube-DL allana el camino a la censura privatizada"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://torrentfreak.com/youtube-dl-hosting-ban-paves-the-way-to-privatized-censorship-230411/",children:"Original"}),'.\nUn tribunal alem\xe1n ha declarado responsable a Uberspace por alojar el sitio web de youtube-dl, una herramienta de c\xf3digo abierto que permite descargar contenidos de YouTube. Uberspace advierte de que el veredicto podr\xeda conducir a una censura privatizada y est\xe1 recurriendo la decisi\xf3n, aunque el tribunal sostiene que Uberspace "puede ser considerado responsable por dudar de la validez de una solicitud de retirada", incluso cuando no estaba claro que la herramienta violara la ley.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35553337",children:"Discussion Service"}),".\nLa prohibici\xf3n del alojamiento de YouTube-DL se considera un impulso hacia la censura privatizada, en la que la RIAA y la MPAA priorizan el dinero y el poder sobre la decencia. Se debate el papel de la propiedad intelectual a la hora de limitar el flujo de informaci\xf3n, y se ofrecen diversos puntos de vista, como la limitaci\xf3n del alcance y la duraci\xf3n. Los usuarios proponen alternativas y denuncian la dependencia de GitHub, al tiempo que debaten sobre la descentralizaci\xf3n y los problemas de la seguridad por oscuridad en la protecci\xf3n anticopia."]}),"\n",(0,s.jsx)(a.h2,{id:"el-arte-de-la-autoingenier\xeda",children:"El arte de la autoingenier\xeda"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://www.howacarworks.com/video-course",children:"Original"}),".\nThe Art of Auto Engineering es un curso completo en v\xeddeo compuesto por m\xe1s de 122 lecciones con 20 horas de metraje en las que se explica con todo lujo de detalles cada una de las piezas de un autom\xf3vil, desde las m\xe1s b\xe1sicas hasta las m\xe1s avanzadas. El curso va acompa\xf1ado de un manual de 200 p\xe1ginas y est\xe1 disponible en l\xednea o en aplicaciones para iOS y Android por un pago \xfanico de 25 d\xf3lares con acceso de por vida, y est\xe1 filmado profesionalmente en calidad 4K con subt\xedtulos completos. El curso ha sido elogiado por los espectadores por su atractiva ense\xf1anza y su excelente valor de producci\xf3n."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35552393",children:"Discussion Service"}),".\nLos usuarios de Hacker News comparten experiencias y recomiendan recursos para aprender ingenier\xeda de automoci\xf3n, incluidos cursos interactivos en v\xeddeo y modelos de coches espec\xedficos. Los comentaristas discuten las ventajas de entender la mec\xe1nica del autom\xf3vil, las limitaciones de confiar \xfanicamente en la IA y ofrecen consejos para reparaciones de bricolaje. Adem\xe1s, los usuarios debaten sobre la utilidad de los cursos y herramientas de pago, y algunos critican la aparici\xf3n de anuncios de clases de pago en el sitio."]}),"\n",(0,s.jsx)(a.h2,{id:"apple-utilizar\xe1-cobalto-100-reciclado-en-sus-bater\xedas-para-2025",children:"Apple utilizar\xe1 cobalto 100% reciclado en sus bater\xedas para 2025"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://www.apple.com/newsroom/2023/04/apple-will-use-100-percent-recycled-cobalt-in-batteries-by-2025/",children:"Original"}),".\nApple ha anunciado su plan de utilizar cobalto 100% reciclado en todas las bater\xedas dise\xf1adas por Apple para 2025, junto con elementos de tierras raras totalmente reciclados para los imanes y esta\xf1o 100% reciclado para las placas de circuitos. Su objetivo es utilizar \xfanicamente materiales reciclados y renovables, y ya obtienen m\xe1s del 95% del tungsteno, casi tres cuartas partes de las tierras raras y m\xe1s de dos tercios del aluminio a partir de material 100% reciclado. Apple utiliza la realidad aumentada (RA) para guiar el desmontaje de los dispositivos de los socios de reciclaje y aumentar la recuperaci\xf3n de elementos de tierras raras, impulsando as\xed un cambio en toda la industria hacia la reducci\xf3n de la dependencia de los minerales reci\xe9n extra\xeddos."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35554270",children:"Discussion Service"}),".\nApple anunci\xf3 su plan de utilizar el 100% de cobalto reciclado en las bater\xedas para 2025 y reducir los residuos pl\xe1sticos, pero los usuarios debaten la eficacia de estos cambios y si la empresa deber\xeda hacer p\xfablica su tecnolog\xeda de reciclaje. El debate sobre las bater\xedas reemplazables por el usuario contin\xfaa, con argumentos de que son negativas para el medio ambiente, mientras que otros sugieren que los m\xe9todos de reciclaje y la ampliaci\xf3n de la vida \xfatil de los productos duraderos pueden resolver este problema. Se alaba el compromiso de Apple con los materiales reciclables y una cadena de suministro neutra en carbono, pero se critica su dise\xf1o y la cadena de suministro de cobalto. Los usuarios debaten sobre la vida \xfatil de los iPhones y los tel\xe9fonos Android, y los m\xe9todos de reciclaje de las bater\xedas. Algunos usuarios sugieren las bater\xedas MagSafe como bater\xeda principal para los iPhones, mientras que otros cuestionan su eficacia."]}),"\n",(0,s.jsx)(a.h2,{id:"logramos-multiplicar-por-6-la-velocidad-de-arranque-de-podman",children:"Logramos multiplicar por 6 la velocidad de arranque de Podman"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://www.redhat.com/sysadmin/speed-containers-podman-raspberry-pi",children:"Original"}),".\nEl motor de contenedores de Red Hat, Podman, consigui\xf3 multiplicar por 6 la velocidad de arranque eliminando procesos innecesarios y abordando peque\xf1as ineficiencias que afectan a aplicaciones cr\xedticas como los coches, donde es esencial el arranque de contenedores casi en tiempo real. El equipo utiliz\xf3 almacenamiento transitorio y solucion\xf3 problemas del kernel, lo que aceler\xf3 el arranque de los contenedores. El uso de la opci\xf3n --transient-store es ideal para dispositivos de borde, aunque no se admiten contenedores de modo mixto."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35551830",children:"Discussion Service"}),".\nPodman, de Red Hat, sextuplica la velocidad de arranque de los veh\xedculos, aunque los usuarios de Discussion Service discuten la sobrecomplicaci\xf3n de los veh\xedculos modernos y plantean preocupaciones sobre su fiabilidad y mantenimiento. La discusi\xf3n deriva en debates sobre el derecho a reparar, el uso de microservicios y contenedores, y el equilibrio entre avances tecnol\xf3gicos y practicidad."]}),"\n",(0,s.jsx)(a.h2,{id:"mejora-de-tailscale-a-trav\xe9s-del-c\xf3digo-abierto-de-apple",children:"Mejora de Tailscale a trav\xe9s del c\xf3digo abierto de Apple"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://tailscale.dev/blog/darwin-spelunking",children:"Original"}),'.\nEl equipo de Tailscale utiliz\xf3 el c\xf3digo abierto de Apple para depurar errores relacionados con la interfaz de red para su versi\xf3n 1.36, bas\xe1ndose en ifconfig para determinar la interfaz de red activa. Cuando Tailscale est\xe1 configurado para utilizar un nodo de salida, \xe9ste se convierte en la ruta por defecto, lo que hace necesaria una correcci\xf3n para "enlazar" de forma consistente las peticiones de red a la interfaz de red activa sin causar tr\xe1fico en bucle. SIOCGIFDELEGATE, disponible a trav\xe9s de ioctl, permite obtener la interfaz f\xedsica subyacente y se implement\xf3 en el c\xf3digo de Tailscale para macOS e iOS.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35559124",children:"Discussion Service"}),".\nLos usuarios de Discussion Service discuten los beneficios y retos del software de c\xf3digo abierto y cerrado en la mejora de Tailscale a trav\xe9s del c\xf3digo abierto de Apple. Algunos clientes de pago dan prioridad a la reputaci\xf3n del producto principal de c\xf3digo abierto de Tailscale, mientras que otros plantean problemas espec\xedficos con Tailscale, como la dificultad para acceder a recursos compartidos de red en Windows 11 y el posible agotamiento de la bater\xeda en dispositivos iOS. El debate pone de relieve la importancia de tener en cuenta varias perspectivas y que Tailscale est\xe1 ganando terreno a Zerotier gracias a su sistema de malla y al despliegue continuo de nuevas funciones, pero algunos usuarios del producto tienen dudas sobre los ingresos y el foso."]}),"\n",(0,s.jsx)(a.h2,{id:"dibujos-animados",children:"Dibujos animados"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://fairanimateddrawings.com/site/home",children:"Original"}),".\nEl repositorio 'Animated Drawings' de Github implementa el algoritmo descrito en el art\xedculo 'A Method for Automatically Animating Children's Drawings of the Human Figure', permitiendo a los usuarios crear animaciones personalizadas con sus propios personajes dibujados a mano. El proceso de instalaci\xf3n es sencillo y los archivos de configuraci\xf3n pueden modificarse para cambiar varias opciones, como los formatos de salida y las im\xe1genes de fondo. El repositorio tambi\xe9n proporciona scripts y modelos para animar dibujos personales, y hay disponible una demostraci\xf3n basada en navegador para un uso r\xe1pido y sencillo."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35561203",children:"Discussion Service"}),".\nEl proyecto Fair Animated Drawings anima dibujos con c\xf3digo, disponible en versi\xf3n para navegador y GitHub. Los usuarios est\xe1n interesados en su potencial para ideas de negocio y esperan una versi\xf3n de aplicaci\xf3n para Android. Un trabajo relevante sobre estimaci\xf3n no fotorrealista de poses llamado Gesture3D parece aplicable a un caso de uso espec\xedfico, y las solicitudes para el YC Summer 2023 est\xe1n abiertas."]}),"\n",(0,s.jsx)(a.h2,{id:"amazon-codewhisperer-gratuito-para-uso-individual-ya-est\xe1-disponible-de-forma-generalizada",children:"Amazon CodeWhisperer, gratuito para uso individual, ya est\xe1 disponible de forma generalizada"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://aws.amazon.com/blogs/aws/amazon-codewhisperer-free-for-individual-use-is-now-generally-available/",children:"Original"}),".\nAmazon CodeWhisperer, un compa\xf1ero de codificaci\xf3n de IA en tiempo real, ya est\xe1 disponible de forma general e incluye un nivel CodeWhisperer Individual gratuito para todos los desarrolladores. La herramienta ayuda a los desarrolladores a escribir c\xf3digo de forma r\xe1pida y segura sin salir de su IDE. CodeWhisperer ofrece sugerencias para casos de uso general en diversos lenguajes y puede filtrar o marcar sugerencias de c\xf3digo que puedan parecerse a determinados datos de entrenamiento de c\xf3digo abierto, lo que ayuda a reducir el riesgo de utilizar c\xf3digo potencialmente sesgado o defectuoso."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35554460",children:"Discussion Service"}),".\nAmazon CodeWhisperer ya est\xe1 disponible de forma general y es compatible con varios lenguajes, incluidos Python, Java, JavaScript, TypeScript y C#. Aunque Copilot es supuestamente mejor que CodeWhisperer, esta \xfaltima es una herramienta \xfatil que puede llevar a que el c\xf3digo generado por IA se convierta en la norma. Adem\xe1s, Amazon ha lanzado CodeGuru Reviewer, una herramienta de IA que escanea el c\xf3digo para identificar problemas y recomendar correcciones para la eficiencia y la reducci\xf3n de costes."]}),"\n",(0,s.jsx)(a.h2,{id:"google-ya-ha-retirado-seis-productos-en-2023",children:"Google ya ha retirado seis productos en 2023"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://toolhub.tech/blog/Google-2023-Shutdown-Spree-6-Products-Pulled-in-Just-4-Months/",children:"Original"}),".\nGoogle ha retirado seis productos en los primeros cuatro meses de 2023, entre ellos el concurso de programaci\xf3n Code Jam, la plataforma de medios sociales Google Currents, la aplicaci\xf3n Street View, la tecnolog\xeda para llevar puesta Google Jacquard, el servicio de juegos en la nube Google Stadia y el router inal\xe1mbrico Google OnHub. Aunque algunos de estos productos ten\xedan m\xe1s de una d\xe9cada, Google se ha enfrentado a cr\xedticas por su costumbre de poner fin bruscamente a servicios populares."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35553421",children:"Discussion Service"}),".\nGoogle ha interrumpido seis productos en 2023, con preocupaciones sobre la transparencia y el etiquetado de los productos, y la falta de apoyo a proyectos fallidos como Google Glass y Google Plus. Aunque la unidad de la nube est\xe1 creciendo con una cuota de mercado del 10%, surgen dudas sobre el compromiso de clientes y desarrolladores y el algoritmo de eliminaci\xf3n de cuentas. Los usuarios debaten soluciones y costes para mejorar la precisi\xf3n de ChatGPT, mientras que la reputaci\xf3n de Google de abandonar proyectos suscita cr\xedticas sobre el soporte de productos para los consumidores."]}),"\n",(0,s.jsx)(a.h2,{id:"ya-est\xe1-disponible-el-c\xf3digo-abierto-de-nvidia-rtx-remix-runtime",children:"Ya est\xe1 disponible el c\xf3digo abierto de Nvidia RTX Remix Runtime"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://www.nvidia.com/en-us/geforce/news/rtx-remix-runtime-open-source-download/",children:"Original"}),".\nNvidia ha lanzado el RTX Remix runtime, una plataforma de modding de c\xf3digo abierto para remasterizar juegos cl\xe1sicos DirectX 8 y 9 con trazado de rutas, texturas mejoradas con IA y activos creados por el usuario. El kit de herramientas RTX Remix permite a los creadores de mods asignar nuevos recursos y luces a una escena remasterizada, y utilizar herramientas de IA para reconstruir el aspecto de cualquier recurso. El tiempo de ejecuci\xf3n de RTX Remix, por su parte, captura una escena de juego, sustituye los activos durante la reproducci\xf3n e inyecta en el juego tecnolog\xeda RTX, como trazado de rutas, DLSS 3 y Reflex."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35552378",children:"Discussion Service"}),".\nNvidia ha lanzado su RTX Remix Runtime de c\xf3digo abierto que permite a los usuarios jugar a juegos antiguos con trazado de rayos en tiempo real, aunque no todos los juegos funcionar\xe1n. Los usuarios de Hacker News discuten la importancia de los controladores de c\xf3digo abierto frente a los controladores propietarios, la reputaci\xf3n de Nvidia y el bajo rendimiento de RTX en hardware que no es de Nvidia. Los usuarios tambi\xe9n especulan sobre un posible favoritismo y sugieren apoyar a los desarrolladores de criptomonedas que implementan esquemas de prueba de trabajo s\xf3lo para GPU. Un usuario se\xf1ala el desarrollo de Remedy de remakes de juegos para PC de Max Payne utilizando Remix y discute los problemas de ritmo de fotogramas y tartamudeo de la tecnolog\xeda."]})]})}function u(e={}){const{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(t,{...e})}):t(e)}}}]);